#!/usr/bin/env python3
"""Optimal quota-constrained follow-up plan and its probe certificate.

Assignments are modelled as a min-cost maximum flow:

    source -> request quota tree -> requests -> offers -> offer quota tree -> sink

A quota node consumes one unit per assignment whose group lies in its subtree,
which its tree edge capacity expresses exactly.  Successive shortest augmenting
paths with Johnson potentials, plus a Dinic blocking flow over the admissible
zero-reduced-cost network, give a maximum-cardinality plan of minimum cost.
Nothing is transmitted: each assignment carries a semantic probe certificate.
"""
from protocols import probe_script

INF = float('inf')


class Network:
    """Residual network over parallel arrays (arc pairs share one index)."""

    def __init__(self, size):
        self.size = size
        self.adj = [[] for _ in range(size)]
        self.to = []
        self.cap = []
        self.cost = []

    def add(self, u, v, capacity, weight=0):
        index = len(self.to)
        self.to.append(v); self.cap.append(capacity); self.cost.append(weight)
        self.adj[u].append(index)
        self.to.append(u); self.cap.append(0); self.cost.append(-weight)
        self.adj[v].append(index + 1)
        return index

    def _levels(self, source, sink, potential):
        level = [-1] * self.size
        level[source] = 0
        adj, to, cap = self.adj, self.to, self.cap
        queue = [source]
        head = 0
        while head < len(queue):
            u = queue[head]; head += 1
            depth = level[u] + 1
            base = potential[u]
            for a in adj[u]:
                if cap[a] <= 0:
                    continue
                v = to[a]
                if level[v] < 0 and self.cost[a] + base == potential[v]:
                    level[v] = depth
                    queue.append(v)
        return level

    def _blocking_flow(self, source, sink, potential, level):
        """Iterative depth-first blocking flow on the admissible network."""
        adj, to, cap, cost = self.adj, self.to, self.cap, self.cost
        pointer = [0] * self.size
        stack = [source]
        path = []
        pushed = 0
        while stack:
            u = stack[-1]
            if u == sink:
                spare = min(cap[a] for a in path)
                cut = 0
                for index, a in enumerate(path):
                    cap[a] -= spare
                    cap[a ^ 1] += spare
                    if cap[a] == 0 and not cut:
                        cut = index
                del path[cut:]
                del stack[cut + 1:]
                pushed += spare
                continue
            arcs = adj[u]
            index = pointer[u]
            base = potential[u]
            depth = level[u] + 1
            while index < len(arcs):
                a = arcs[index]
                v = to[a]
                if cap[a] > 0 and level[v] == depth and cost[a] + base == potential[v]:
                    break
                index += 1
            if index == len(arcs):
                pointer[u] = index
                level[u] = -1
                stack.pop()
                if path:
                    path.pop()
            else:
                pointer[u] = index + 1
                stack.append(to[arcs[index]])
                path.append(arcs[index])
        return pushed

    def minimum_cost_maximum_flow(self, source, sink):
        """Return (flow, cost); the flow of every value is of minimum cost."""
        adj, to, cap, cost = self.adj, self.to, self.cap, self.cost
        size = self.size
        potential = [0] * size
        import heapq
        heappush, heappop = heapq.heappush, heapq.heappop
        flow = 0
        while True:
            dist = [INF] * size
            dist[source] = 0
            heap = [(0, source)]
            while heap:
                distance, u = heappop(heap)
                if distance != dist[u]:
                    continue
                base = distance + potential[u]
                for a in adj[u]:
                    if cap[a] <= 0:
                        continue
                    v = to[a]
                    trial = base + cost[a] - potential[v]
                    if trial < dist[v]:
                        dist[v] = trial
                        heappush(heap, (trial, v))
            limit = dist[sink]
            if limit == INF:
                break
            for v in range(size):
                found = dist[v]
                potential[v] += found if found < limit else limit
            while True:
                level = self._levels(source, sink, potential)
                if level[sink] < 0:
                    break
                pushed = self._blocking_flow(source, sink, potential, level)
                if pushed <= 0:
                    break
                flow += pushed
        total = 0
        for a in range(0, len(to), 2):
            used = cap[a ^ 1]
            if used and cost[a]:
                total += used * cost[a]
        return flow, total


def _reachable_pairs(context, active):
    """Return per-request allowed offers after every stated admission test."""
    leases = context['leases']
    pairs = {}
    listed = {}
    for name, offer in context['offers'].items():
        if offer['capacity'] <= 0:
            continue
        if any(context['offer_quotas'][node]['capacity'] <= 0
               for node in context['offer_paths'][name and offer['group']]):
            continue
        network = offer['network']
        base = int(network.network_address)
        span = 1 << (128 - network.prefixlen)
        moment = offer['time']
        service = offer['service']
        keep = []
        for request_id in offer['requests']:
            if not active.get(request_id):
                continue
            request = context['requests'][request_id]
            if request['service'] != service or request['at'] > moment:
                continue
            if moment >= leases[request['lease']]['end']:
                continue
            address = request['address']
            if not base <= address < base + span:
                continue
            keep.append((request_id, offer['id']))
        if keep:
            pairs[offer['id']] = keep
    return pairs


def _build(context, pairs, active):
    """Assemble the flow network; return (network, source, sink, request arcs)."""
    quotas_r = context['request_quotas']
    paths_r = context['request_paths']
    quotas_o = context['offer_quotas']
    paths_o = context['offer_paths']

    used_requests = []
    offer_uses = {}
    for offer_id, rows in pairs.items():
        for request_id, _ in rows:
            offer_uses.setdefault(request_id, []).append(offer_id)
    for request_id in sorted(offer_uses):
        if any(quotas_r[node]['capacity'] <= 0 for node in paths_r[
                context['requests'][request_id]['group']]):
            continue
        used_requests.append(request_id)

    source = 0
    sink = 1
    next_id = [2]

    def node(key, table):
        found = table.get(key)
        if found is None:
            found = table[key] = next_id[0]
            next_id[0] += 1
        return found

    request_nodes = {}
    offer_nodes = {}
    request_group_nodes = {}
    offer_group_nodes = {}
    for request_id in used_requests:
        request_nodes[request_id] = node(('r', request_id), request_nodes)
        for name in paths_r[context['requests'][request_id]['group']]:
            node(('rq', name), request_group_nodes)
    for request_id in used_requests:
        for offer_id in offer_uses[request_id]:
            offer_nodes[offer_id] = node(('o', offer_id), offer_nodes)
            for name in paths_o[context['offers'][offer_id]['group']]:
                node(('oq', name), offer_group_nodes)

    network = Network(next_id[0])
    # Request quota forest, flowing away from the source.
    for name, table in (('rq', request_group_nodes), ('oq', offer_group_nodes)):
        pass
    for key, index in list(request_group_nodes.items()):
        name = key[1]
        capacity = quotas_r[name]['capacity']
        parent = quotas_r[name]['parent']
        if parent is None or ('rq', parent) not in request_group_nodes:
            network.add(source, index, capacity)
        else:
            network.add(request_group_nodes[('rq', parent)], index, capacity)
    for request_id in used_requests:
        group = request_group_nodes[
            ('rq', context['requests'][request_id]['group'])]
        network.add(group, request_nodes[request_id], 1)
    pair_arcs = []
    for request_id in used_requests:
        tail = request_nodes[request_id]
        for offer_id in offer_uses[request_id]:
            pair_arcs.append((request_id, offer_id,
                              network.add(tail, offer_nodes[offer_id], 1)))
    for offer_id, index in offer_nodes.items():
        offer = context['offers'][offer_id]
        group = offer_group_nodes[('oq', offer['group'])]
        network.add(index, group, offer['capacity'], offer['cost'])
    for key, index in list(offer_group_nodes.items()):
        name = key[1]
        capacity = quotas_o[name]['capacity']
        parent = quotas_o[name]['parent']
        if parent is None or ('oq', parent) not in offer_group_nodes:
            network.add(index, sink, capacity)
        else:
            network.add(index, offer_group_nodes[('oq', parent)], capacity)
    return network, pair_arcs


def solve(context, active):
    """Return the plan object: maximum assignments at minimum total cost."""
    pairs = _reachable_pairs(context, active)
    if not pairs or not context['requests']:
        return {'resolved': 0, 'cost': 0, 'assignments': []}
    network, pair_arcs = _build(context, pairs, active)
    if network.size <= 2:
        return {'resolved': 0, 'cost': 0, 'assignments': []}
    flow, cost = network.minimum_cost_maximum_flow(0, 1)
    kinds = context['services']
    chosen = []
    for request_id, offer_id, arc in pair_arcs:
        if network.cap[arc] == 0:          # unit of flow used this pair
            chosen.append((request_id, offer_id))
    chosen.sort()
    scripts = {}
    assignments = []
    for request_id, offer_id in chosen:
        kind = kinds[context['requests'][request_id]['service']]
        script = scripts.get(kind)
        if script is None:
            script = scripts[kind] = probe_script(kind)
        assignments.append({'request': request_id, 'offer': offer_id,
                            'send': list(script[0]), 'finish': list(script[1])})
    return {'resolved': len(assignments), 'cost': cost, 'assignments': assignments}
